-- Phase 06: canonical physical graph and onboarding pipeline. Expand-only.
CREATE TABLE neighborhoods (id UUID PRIMARY KEY, city_id BIGINT NOT NULL REFERENCES cities(id), name VARCHAR(120) NOT NULL, normalized_name VARCHAR(120) NOT NULL, UNIQUE(city_id, normalized_name));
CREATE TABLE geo_clusters (id UUID PRIMARY KEY, city_id BIGINT NOT NULL REFERENCES cities(id), neighborhood_id UUID REFERENCES neighborhoods(id), type VARCHAR(16) NOT NULL CHECK(type IN ('STREET','MARKET','MALL')), name VARCHAR(180) NOT NULL, normalized_name VARCHAR(180) NOT NULL, lat DOUBLE PRECISION, lng DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(city_id, type, normalized_name));
CREATE TABLE buildings (id UUID PRIMARY KEY, cluster_id UUID NOT NULL REFERENCES geo_clusters(id), name VARCHAR(180) NOT NULL, normalized_name VARCHAR(180) NOT NULL, address TEXT, lat DOUBLE PRECISION, lng DOUBLE PRECISION, UNIQUE(cluster_id, normalized_name));
CREATE TABLE entrances (id UUID PRIMARY KEY, building_id UUID NOT NULL REFERENCES buildings(id), label VARCHAR(80) NOT NULL, lat DOUBLE PRECISION, lng DOUBLE PRECISION, UNIQUE(building_id, label));
CREATE TABLE indoor_floors (id UUID PRIMARY KEY, building_id UUID NOT NULL REFERENCES buildings(id), level_number INTEGER NOT NULL, label VARCHAR(80) NOT NULL, UNIQUE(building_id, level_number));
CREATE TABLE corridors (id UUID PRIMARY KEY, floor_id UUID NOT NULL REFERENCES indoor_floors(id), label VARCHAR(80) NOT NULL, UNIQUE(floor_id, label));
CREATE TABLE indoor_units (id UUID PRIMARY KEY, floor_id UUID NOT NULL REFERENCES indoor_floors(id), corridor_id UUID REFERENCES corridors(id), unit_code VARCHAR(40) NOT NULL, UNIQUE(floor_id, unit_code));
CREATE INDEX idx_geo_clusters_point ON geo_clusters(lat, lng) WHERE lat IS NOT NULL AND lng IS NOT NULL;
CREATE TABLE shop_applications (id UUID PRIMARY KEY, applicant_user_id BIGINT NOT NULL REFERENCES users(id), agent_user_id BIGINT REFERENCES users(id), merchant_organization_id UUID REFERENCES merchant_organizations(id), cluster_id UUID REFERENCES geo_clusters(id), building_id UUID REFERENCES buildings(id), unit_id UUID REFERENCES indoor_units(id), name VARCHAR(180) NOT NULL, normalized_name VARCHAR(180) NOT NULL, phone VARCHAR(30), normalized_phone VARCHAR(30), address TEXT, lat DOUBLE PRECISION, lng DOUBLE PRECISION, indoor_x DOUBLE PRECISION, indoor_y DOUBLE PRECISION, precise_location_consented_at TIMESTAMPTZ, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', duplicate_of_id UUID REFERENCES shop_applications(id), idempotency_key VARCHAR(120) NOT NULL, review_reason TEXT, appeal_text TEXT, reviewed_by_user_id BIGINT REFERENCES users(id), reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(applicant_user_id, idempotency_key), CHECK ((unit_id IS NULL OR building_id IS NOT NULL) AND (indoor_x IS NULL OR unit_id IS NOT NULL)));
CREATE INDEX idx_shop_applications_queue ON shop_applications(status, created_at);
CREATE INDEX idx_shop_applications_duplicate ON shop_applications(normalized_name, normalized_phone, unit_id);
CREATE TABLE verification_checks (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES shop_applications(id), type VARCHAR(40) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', checked_by_user_id BIGINT REFERENCES users(id), note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), checked_at TIMESTAMPTZ);
CREATE TABLE application_evidence (id UUID PRIMARY KEY, application_id UUID NOT NULL REFERENCES shop_applications(id), object_key VARCHAR(255) NOT NULL, media_type VARCHAR(100) NOT NULL, sha256 VARCHAR(64) NOT NULL, classification VARCHAR(16) NOT NULL DEFAULT 'PRIVATE', retention_until TIMESTAMPTZ, uploaded_by_user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(application_id, sha256));
CREATE TABLE shop_claims (id UUID PRIMARY KEY, application_id UUID NOT NULL UNIQUE REFERENCES shop_applications(id), claimant_user_id BIGINT NOT NULL REFERENCES users(id), status VARCHAR(20) NOT NULL DEFAULT 'PENDING_OTP', otp_verified_at TIMESTAMPTZ, approved_by_user_id BIGINT REFERENCES users(id), approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE onboarding_audit_events (id UUID PRIMARY KEY, application_id UUID REFERENCES shop_applications(id), actor_user_id BIGINT REFERENCES users(id), action VARCHAR(64) NOT NULL, detail_json JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
